#[doc = r"Estimate volumetric water content at -33 kPa with the published GMDH polynomial.

# Arguments

  * soil_organic_carbon: Soil organic carbon content by mass. (% mass)
  * clay: Clay content by mass. (% mass)
  * sand: Sand content by mass; clay plus sand must not exceed 100. (% mass)

# Returns

  * theta_33: Volumetric soil water content at -33 kPa. (cm³/cm³)

# Models

  * h(theta): GMDH polynomial point estimate at -33 kPa

# Notes

Prediction target: Volumetric soil water content at -33 kPa.
The polynomial calculates volume percent; the public output divides the result by 100.

# Warnings

Apply only within the source ranges and with clay plus sand no greater than 100%."]
#[cfg_attr(feature = "inline", inline)]
#[must_use]
pub fn calc_ptf_rawls2003_soc_theta33_gmdh(soil_organic_carbon: f64, clay: f64, sand: f64) -> f64 {
    let x = -0.837531f64 + 0.430183f64 * soil_organic_carbon;
    let y = -1.40744f64 + 0.0661969f64 * clay;
    let z = -1.51866f64 + 0.0393284f64 * sand;
    let x_squared = x.powi(2);
    let x_cubed = x.powi(3);
    let y_squared = y.powi(2);
    let y_cubed = y.powi(3);
    let z_squared = z.powi(2);
    let z_cubed = z.powi(3);
    let xy = x * y;
    let polynomial = 0.0461615f64 + 0.290955f64 * x - 0.0496845f64 * x_squared
        + 0.00704802f64 * x_cubed
        + 0.269101f64 * y
        - 0.176528f64 * xy
        + 0.0543138f64 * x_squared * y
        + 0.1982f64 * y_squared
        - 0.060699f64 * y_cubed
        - 0.320249f64 * z
        - 0.0111693f64 * x_squared * z
        + 0.14104f64 * y * z
        + 0.0657345f64 * xy * z
        - 0.102026f64 * y_squared * z
        - 0.04012f64 * z_squared
        + 0.160838f64 * x * z_squared
        - 0.121392f64 * y * z_squared
        - 0.0616676f64 * z_cubed;
    let theta_33_volume_percent = 29.7528f64 + 10.3544f64 * polynomial;
    theta_33_volume_percent / 100.0f64
}
