pub fn calc_ptf_rawls2003_soc_theta1500_gmdh(
    soil_organic_carbon: f64,
    clay: f64,
    sand: f64,
) -> f64 {
    let x = -0.837531f64 + 0.430183f64 * soil_organic_carbon;
    let y = -1.40744f64 + 0.0661969f64 * clay;
    let z = -1.51866f64 + 0.0393284f64 * sand;
    let x_squared = x.powi(2);
    let x_cubed = x.powi(3);
    let y_squared = y.powi(2);
    let y_cubed = y.powi(3);
    let z_squared = z.powi(2);
    let z_cubed = z.powi(3);
    let xy = x * y;
    let polynomial = 0.06865f64 + 0.108713f64 * x - 0.0157225f64 * x_squared
        + 0.00102805f64 * x_cubed
        + 0.886569f64 * y
        - 0.223581f64 * xy
        + 0.0126379f64 * x_squared * y
        - 0.017059f64 * y_squared
        + 0.0135266f64 * x * y_squared
        - 0.0334434f64 * y_cubed
        - 0.0535182f64 * z
        - 0.0354271f64 * x * z
        - 0.00261313f64 * x_squared * z
        - 0.154563f64 * y * z
        - 0.0160219f64 * xy * z
        - 0.0400606f64 * y_squared * z
        - 0.104875f64 * z_squared
        + 0.0159857f64 * x * z_squared
        - 0.0671656f64 * y * z_squared
        - 0.0260699f64 * z_cubed;
    let theta_1500_volume_percent = 14.2568f64 + 7.36318f64 * polynomial;
    theta_1500_volume_percent / 100.0f64
}
